210	// maxRenderBytes bounds the rendered transcript so a long session can't produce
211	// a payload that blows past WebSocket message-size limits or bogs the client's
212	// text view. The tail (most recent conversation) is kept.
213	const maxRenderBytes = 128 * 1024
214	
215	// capTail trims s to at most maxRenderBytes, keeping the end and starting at a
216	// line boundary so a message isn't cut mid-line.
217	func capTail(s string) string {
218		if len(s) <= maxRenderBytes {
219			return s
220		}
221		s = s[len(s)-maxRenderBytes:]
222		if i := strings.IndexByte(s, '\n'); i >= 0 && i+1 < len(s) {
223			s = s[i+1:]
224		}
225		return s
226	}
